module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
// Define parameters for different states
parameter INITIAL = 2'b00;
parameter STATE_1 = 2'b01;
parameter STATE_2 = 2'b10;
parameter END = 2'b11;
// Register to hold the current state
reg [1:0] state;
// Combinational logic to calculate the next state
wire [1:0] next_state;
assign next_state = (state == INITIAL && data_in == 1'b1) ? STATE_1 :
                   (state == STATE_1 && data_in == 1'b1) ? STATE_2 :
                   (state == STATE_2 && data_in == 1'b0) ? END :
                   INITIAL;
// Always block to update state and output
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= INITIAL;
        data_out <= 1'b0;
    end else begin
        state <= next_state;
        case(state)
            INITIAL: data_out <= 1'b0;
            STATE_1: data_out <= 1'b0;
            STATE_2: data_out <= 1'b0;
            END:     data_out <= 1'b1;
            default: data_out <= 1'b0;
        endcase
    end
end
endmodule
